/** Byte length of a data-URL payload (base64 body only — not the `data:` prefix). */
export function estimateDataUrlBytes(dataUrl: string): number {
  const comma = dataUrl.indexOf(',');
  const b64 = (comma >= 0 ? dataUrl.slice(comma + 1) : dataUrl).replace(/\s/g, '');
  const padding = b64.endsWith('==') ? 2 : b64.endsWith('=') ? 1 : 0;
  return Math.max(0, Math.floor((b64.length * 3) / 4) - padding);
}

/** Minimal valid 1×1 JPEG for simulate / fixture uploads. */
export const MINIMAL_JPEG_DATA_URL =
  'data:image/jpeg;base64,';
